/**
 * Validity of the JSON Schemas generated with zod2JsonSchemaDefinitions for all the schemas of the
 * test fixtures (supported schemas of every transpiler, layered models, issue cases): for every
 * target they must be valid JSON Schemas, without unresolved references or `id` keywords, and
 * validate the same data with the same annotations as the JSON Schemas generated by Zod with the
 * same definitions without the zod-to-x `override`.
 */
import { z } from "zod/v4";
import { createGenericType, extendZod, useGenericType, Zod2XConverters } from "../../dist";
extendZod(z);

import { describe, expect, test } from "vitest";

import { userApi, userDtos, userModels } from "../common/layered_schemas";
import { tsSupportedSchemasModel as layeredStrings } from "../test_zod2ts/ts_supported_schemas.layered";
import {
    compile,
    findProblems,
    getMutations,
    isZodSupported,
    Params,
    Target,
    TARGETS,
    toJsonSchema,
    toZodJsonSchema,
    withoutIds,
    zodVersion,
} from "./json_schema_checks";
import { UserModel } from "./user_schema";

const isZodSchema = (value: unknown): value is z.ZodType =>
    typeof value === "object" && value !== null && "_zod" in value;

/** Schemas of the exports of a module: schemas, members of objects and models, and results of
 * functions without parameters (schema factories). */
function collectSchemas(modules: Record<string, Record<string, unknown>>): [string, z.ZodType][] {
    const schemas: [string, z.ZodType][] = [];
    const seen = new Set<unknown>();
    const add = (name: string, value: unknown) => {
        if (isZodSchema(value) && !seen.has(value)) {
            seen.add(value);
            schemas.push([name, value]);
        }
    };
    const addMembers = (name: string, value: unknown) => {
        if (typeof value === "object" && value !== null && !isZodSchema(value)) {
            for (const [key, member] of Object.entries(value)) {
                add(`${name}.${key}`, member);
            }
        }
    };

    for (const [path, module] of Object.entries(modules)) {
        const file = path.replace(/^.*\/test\//, "");
        for (const [name, value] of Object.entries(module)) {
            add(`${file}:${name}`, value);
            addMembers(`${file}:${name}`, value);
            if (typeof value === "function" && value.length === 0 && !/^[A-Z]/.test(name)) {
                try {
                    addMembers(`${file}:${name}()`, (value as () => unknown)());
                } catch {
                    // Not a schema factory.
                }
            }
        }
    }

    return schemas;
}

const fixtures = import.meta.glob<Record<string, unknown>>(
    [
        "../test_zod2*/*supported_schemas*.ts",
        "../common/zod_schemas.ts",
        "../common/layered_*.ts",
        "../test_issues/*/*/case_*.ts",
        "!../test_issues/*/*/*.test-suite.ts",
        "./user_schema.ts",
    ],
    { eager: true }
);

// Schemas that combine the cases handled by the zod-to-x `override`.
const Status = z.enum(["active", "inactive"]).describe("Status").zod2x("Status");
const Address = z.object({ street: z.string() }).describe("Address").zod2x("Address");
const AddressHandle = Address.clone();
const Name = z.string().min(1).describe("Name");
const NameHandle = Name.clone();
const Response = z.object({ data: createGenericType("T"), page: z.number() }).zod2x("Response");
const Shape = z
    .intersection(z.object({ a: z.string() }).zod2x("A"), z.object({ b: z.number() }).zod2x("B"))
    .describe("Shape")
    .zod2x("Shape");
const Tree: z.ZodType = z
    .object({ name: z.string(), children: z.lazy(() => z.array(Tree.clone())) })
    .zod2x("Tree");

const edgeCases = {
    copies: z
        .object({
            copy: AddressHandle.clone(),
            described: AddressHandle.clone().describe("Described"),
            titled: AddressHandle.clone().meta({ title: "Titled" }),
            refined: AddressHandle.clone().refine(() => true),
            strict: Address.strict(),
            status: Status,
            otherStatus: Status.describe("Other status"),
        })
        .zod2x("EdgeCopies"),
    checks: z
        .object({
            min: NameHandle.min(3),
            max: NameHandle.clone().max(5),
            both: Name.clone().clone().min(2).max(4),
        })
        .zod2x("EdgeChecks"),
    wrappers: z
        .object({
            nullable: AddressHandle.clone().nullable(),
            optional: AddressHandle.clone().optional(),
            array: z.array(AddressHandle.clone().describe("Item")),
            record: z.record(z.string(), AddressHandle.clone()),
            tuple: z.tuple([AddressHandle.clone(), Status.clone()]),
            readonly: AddressHandle.clone().readonly(),
            withDefault: Status.clone().default("active"),
        })
        .zod2x("EdgeWrappers"),
    generics: z
        .object({
            unnamed: useGenericType(Response, { data: z.string() }, true),
            unnamedRef: useGenericType(Response, { data: AddressHandle.clone() }, true),
            named: useGenericType(Response, { data: Address }, true).zod2x("AddressResponse"),
        })
        .zod2x("EdgeGenerics"),
    intersections: z
        .object({ shape: Shape.clone().clone(), described: Shape.clone().describe("Other shape") })
        .zod2x("EdgeIntersections"),
    recursive: z.object({ tree: Tree, copy: Tree.clone().clone() }).zod2x("EdgeRecursive"),
    // Copies of a layered alias of a string with checks next to the reference.
    checkedAliases: z
        .object({
            min: (layeredStrings.stringItem as z.ZodString).min(3),
            max: (layeredStrings.stringItem as z.ZodString).clone().max(9).describe("Max"),
        })
        .zod2x("EdgeCheckedAliases"),
};

const corpus: [string, z.ZodType][] = [
    ...collectSchemas(fixtures),
    ...Object.entries(edgeCases).map(([name, schema]): [string, z.ZodType] => [
        `edge.${name}`,
        schema,
    ]),
];

const cases = corpus.flatMap(([name, schema]) =>
    TARGETS.map((target): [string, string, z.ZodType] => [name, target, schema])
);

describe.runIf(isZodSupported)(`JSON Schema validity (Zod ${zodVersion})`, () => {
    test("The corpus covers the fixtures", () => {
        expect(Object.keys(fixtures).length).toBeGreaterThanOrEqual(36);
        expect(corpus.length).toBeGreaterThan(300);
    });

    test.each(cases)("%s (%s)", (_name, target, schema) => {
        expect(findProblems(schema, target as Target)).toEqual([]);
    });

    test.each(cases)("%s (%s, input)", (_name, target, schema) => {
        expect(findProblems(schema, target as Target, { io: "input" })).toEqual([]);
    });

    test.each(cases)("%s (%s, reused schemas as definitions)", (_name, target, schema) => {
        expect(findProblems(schema, target as Target, { reused: "ref" })).toEqual([]);
    });
});

describe.runIf(isZodSupported)(`JSON Schema data validation (Zod ${zodVersion})`, () => {
    const entity = {
        id: "123e4567-e89b-12d3-a456-426614174000",
        name: "Name",
        email: "user@example.com",
        age: 30,
        role: "Admin",
    };
    const { id: _id, ...dto } = entity;
    const address = { street: "Main" };

    const samples: [string, z.ZodType, unknown][] = [
        ["userEntity", userModels.userEntity, entity],
        ["createUserUseCaseDto", userDtos.createUserUseCaseDto, dto],
        ["updateUserUseCaseDto", userDtos.updateUserUseCaseDto, dto],
        ["updateUserUseCaseResultDto", userDtos.updateUserUseCaseResultDto, entity],
        ["reqUpdateUser", userApi.reqUpdateUser, dto],
        ["resUpdateUser", userApi.resUpdateUser, entity],
        ["resUpdateUserMulti", userApi.resUpdateUserMulti, { amount: 2, data: [entity, entity] }],
        [
            "edge.copies",
            edgeCases.copies,
            {
                copy: address,
                described: address,
                titled: address,
                refined: address,
                strict: address,
                status: "active",
                otherStatus: "inactive",
            },
        ],
        ["edge.checks", edgeCases.checks, { min: "abcd", max: "ab", both: "abc" }],
        [
            "edge.wrappers",
            edgeCases.wrappers,
            {
                nullable: null,
                optional: address,
                array: [address],
                record: { a: address },
                tuple: [address, "active"],
                readonly: address,
                withDefault: "inactive",
            },
        ],
        [
            "edge.generics",
            edgeCases.generics,
            {
                unnamed: { data: "a", page: 1 },
                unnamedRef: { data: address, page: 1 },
                named: { data: address, page: 2 },
            },
        ],
        [
            "edge.recursive",
            edgeCases.recursive,
            {
                tree: { name: "a", children: [{ name: "b", children: [] }] },
                copy: { name: "c", children: [] },
            },
        ],
        ["UserModel.friends (recursive)", z.object({ friends: UserModel.shape.friends }), {}],
    ];

    test.each(
        samples.flatMap(([name, schema, value]) =>
            (["draft-2020-12", "draft-07"] as const).map(
                (target): [string, string, z.ZodType, unknown] => [name, target, schema, value]
            )
        )
    )("%s (%s)", (_name, target, schema, value) => {
        const t = target as "draft-2020-12" | "draft-07";
        const params = { target: t, unrepresentable: "any" } as const;
        const validate = compile(toJsonSchema(schema, params), t)!;
        // Zod 4.3 emits the `id` of the definitions without the zod-to-x override.
        const validateZod = compile(withoutIds(toZodJsonSchema(schema, params)), t)!;

        expect(validate(value)).toBe(true);
        expect(schema.safeParse(value).success).toBe(true);

        for (const mutation of getMutations(value)) {
            expect([mutation, validate(mutation)]).toEqual([mutation, validateZod(mutation)]);
        }
    });

    test("The JSON Schemas reject data rejected by Zod", () => {
        const validate = compile(
            toJsonSchema(userDtos.updateUserUseCaseResultDto),
            "draft-2020-12"
        )!;

        for (const mutation of getMutations(entity)) {
            if (!userDtos.updateUserUseCaseResultDto.safeParse(mutation).success) {
                expect([mutation, validate(mutation)]).toEqual([mutation, false]);
            }
        }
    });
});

describe.runIf(isZodSupported)("Intersections of named objects", () => {
    // In output JSON Schemas, each object rejects the properties of the other one
    // (`additionalProperties: false`): the `allOf` of their references, which Zod generates, does
    // not validate any object. zod-to-x merges them as `z.intersection` does.
    const A = z.object({ a: z.string() }).zod2x("A");
    const B = z.object({ b: z.number() }).zod2x("B");
    const AB = z.intersection(A, B).zod2x("AB");
    const value = { a: "a", b: 1 };

    test.each(["draft-2020-12", "draft-07"] as const)("Output JSON Schemas (%s)", (target) => {
        const validate = compile(toJsonSchema(AB, { target }), target)!;
        const validateZod = compile(withoutIds(toZodJsonSchema(AB, { target })), target)!;

        expect(findProblems(AB, target)).toEqual([]);
        expect(AB.safeParse(value).success).toBe(true);
        expect(validateZod(value)).toBe(false);
        expect(validate(value)).toBe(true);
        expect(validate({ a: "a" })).toBe(false);
        expect(validate({ a: "a", b: 1, c: 2 })).toBe(false);
    });

    test.each(["draft-2020-12", "draft-07"] as const)("Input JSON Schemas (%s)", (target) => {
        const validate = compile(toJsonSchema(AB, { target, io: "input" }), target)!;

        expect(validate(value)).toBe(true);
        expect(validate({ a: "a" })).toBe(false);
    });

    test("The checks detect intersections that are not merged", () => {
        // The JSON Schema generated by Zod, without the `id` that Zod 4.3 emits.
        const params = Zod2XConverters.zod2JsonSchemaDefinitions();
        const unmerged: Params = {
            metadata: params.metadata,
            override: ({ jsonSchema }) => {
                delete (jsonSchema as Record<string, unknown>).id;
            },
        };

        expect(findProblems(AB, "draft-2020-12")).toEqual([]);
        expect(findProblems(AB, "draft-2020-12", {}, unmerged)).toContain(
            "validates other data than the JSON Schema generated by Zod"
        );
    });
});

/**
 * The checks must detect overrides that change the JSON Schemas: otherwise, the corpus tests
 * would pass with an invalid `override`.
 */
describe.runIf(isZodSupported)("JSON Schema checks detect invalid overrides", () => {
    // The zod-to-x override followed by a defect, so that each test checks one defect.
    const withOverride = (defect: Params["override"]): Params => {
        const params = Zod2XConverters.zod2JsonSchemaDefinitions();
        return {
            metadata: params.metadata,
            override: (ctx) => {
                params.override(ctx);
                defect(ctx);
            },
        };
    };
    // Fixtures with every kind of copy handled by the zod-to-x override.
    const subset = corpus.filter(
        ([name]) =>
            name.startsWith("edge.") ||
            name.includes("layered_schemas") ||
            name.includes(".layered.ts")
    );
    const problemsWith = (params: Params) =>
        subset.flatMap(([name, schema]) =>
            TARGETS.flatMap((target) =>
                findProblems(schema, target, {}, params).map(
                    (problem) => `${name} ${target}: ${problem}`
                )
            )
        );

    test("Removing the keywords next to references", () => {
        const problems = problemsWith(
            withOverride(({ jsonSchema }) => {
                const json = jsonSchema as Record<string, unknown>;
                const isReference =
                    "$ref" in json ||
                    (Array.isArray(json.allOf) && json.allOf.some((member: any) => member.$ref));
                if (isReference) {
                    for (const key of Object.keys(json)) {
                        if (key !== "$ref" && key !== "allOf" && key !== "id") {
                            delete json[key];
                        }
                    }
                }
            })
        );

        // Removing `minLength` next to the reference changes the validated data (or leaves a
        // keyword that the strict mode of Ajv rejects).
        const checks = problems.filter((problem) => problem.startsWith("edge.checkedAliases "));
        expect(problems.some((problem) => problem.includes("annotations differ"))).toBe(true);
        expect(checks.length).toBeGreaterThan(0);
        expect(
            checks.some(
                (problem) =>
                    problem.includes("validates other data") ||
                    problem.includes("invalid JSON Schema")
            )
        ).toBe(true);
    });

    test("Leaving references with other keywords before draft 2019-09", () => {
        const problems = problemsWith(
            withOverride((ctx) => {
                const json = ctx.jsonSchema as Record<string, any>;
                if (Array.isArray(json.allOf) && json.allOf.length === 1 && json.allOf[0].$ref) {
                    json.$ref = json.allOf[0].$ref;
                    delete json.allOf;
                }
            })
        );

        expect(problems.some((problem) => problem.includes("ignored by the target"))).toBe(true);
    });

    test("Leaving the id keyword", () => {
        // Zod 4.4+ removes an `id` equal to the name of the definition, but not other ones.
        const problems = problemsWith(
            withOverride(({ zodSchema, jsonSchema }) => {
                const id = Zod2XConverters.zod2JsonSchemaDefinitions().metadata.get(zodSchema)?.id;
                if (id !== undefined) {
                    (jsonSchema as Record<string, unknown>).id = `${id}Id`;
                }
            })
        );

        expect(problems.some((problem) => problem.includes('"id" keyword'))).toBe(true);
    });

    test("Breaking references", () => {
        const problems = problemsWith(
            withOverride(({ jsonSchema }) => {
                const json = jsonSchema as Record<string, unknown>;
                if (typeof json.$ref === "string") {
                    json.$ref = `${json.$ref}Missing`;
                }
            })
        );

        expect(problems.some((problem) => problem.includes("Unresolved reference"))).toBe(true);
    });
});

describe.skipIf(isZodSupported)(`Unsupported Zod version (Zod ${zodVersion})`, () => {
    test("zod2JsonSchemaDefinitions throws instead of generating invalid JSON Schemas", () => {
        expect(() => Zod2XConverters.zod2JsonSchemaDefinitions()).toThrow(/requires Zod 4\.3\.6/);
    });
});
